<div class="d-flex justify-content-between align-items-center mb-3"><div><h1 class="h3 mb-1">Expense #<?=e($expense['id'])?></h1><p class="text-muted mb-0">Expense details and audit-ready information.</p></div><div><a href="<?=url('expenses')?>" class="btn btn-outline-secondary">Back</a><?php if(can('expenses.edit') && (int)$expense['user_id']===(int)auth_user()['id']):?><a href="<?=url('expenses/'.$expense['id'].'/edit')?>" class="btn btn-primary">Edit</a><?php endif;?></div></div><div class="card"><div class="card-body"><div class="row g-4"><div class="col-md-4"><div class="text-muted">Amount</div><div class="h2"><?=money($expense['amount'])?></div></div><div class="col-md-4"><div class="text-muted">Date</div><div class="h5"><?=e($expense['expense_date'])?></div></div><div class="col-md-4"><div class="text-muted">Status</div><span class="badge bg-<?=($expense['status']==='posted'?'success':'secondary')?>"><?=e($expense['status'])?></span></div><div class="col-md-6"><div class="text-muted">Category</div><div class="h5"><?=e($expense['category_name'])?></div></div><div class="col-md-6"><div class="text-muted">Account</div><div class="h5"><?=e($expense['account_name'])?></div></div><div class="col-12"><div class="text-muted">Description</div><div><?=e($expense['description'])?></div></div><div class="col-12"><div class="text-muted">Notes</div><div><?=nl2br(e($expense['notes']))?></div></div></div><?php if(can('expenses.delete') && (int)$expense['user_id']===(int)auth_user()['id']):?><hr><form method="post" action="<?=url('expenses/'.$expense['id'].'/delete')?>" onsubmit="return confirm('Delete this expense? This will restore the account balance.');"><?=csrf_field()?><button class="btn btn-outline-danger">Delete Expense</button></form><?php endif;?></div></div>